/* One key, explicit model profiles, independent local service. */
names.bai=['多模型聚合采样','Multi-model sampling'];
let baiToken='',baiState={configured:false,models:[],profiles:[]},baiMarket='CN',baiSelected=new Set(),baiRuns=[],baiActive=null,baiTimer=null,baiDraft={CN:{},US:{}};
const baiLocal=()=>['127.0.0.1','localhost'].includes(location.hostname)&&location.port==='8771';
async function baiFetch(path,body){if(!baiToken)throw Error('请先打开 B.AI 本机工作台');const r=await fetch('/api/bai/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+baiToken,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.error||'请求失败');return j}
function baiCapture(){for(const k of ['brand','website','skus','questions'])if($('#bai-'+k))baiDraft[baiMarket][k]=$('#bai-'+k).value}
function baiChangeMarket(m){baiCapture();baiMarket=m;baiSelected.clear();baiActive=null;clearTimeout(baiTimer);render()}
function baiName(id,r=baiActive){return r?.configuration?.[id]?.name||baiState.profiles.find(p=>p.id===id)?.name||id}
function baiPage(){const d=baiDraft[baiMarket];return `<div class="diag-hero"><div><div class="diag-eyebrow">ONE KEY · MULTIPLE MODELS · ${baiMarket}</div><h2>一把密钥，比较多个模型。</h2><p>中国与美国分别运行题集，逐模型、逐 SKU 查看真实回答与提及分。</p></div><a class="primary button" href="http://127.0.0.1:8771/#/w/demo/bai" target="_blank" rel="noopener">打开聚合采样执行器 ↗</a></div><div class="notice">${baiLocal()?'独立执行器已启动，原有 OpenAI / Gemini 会话继续保留在 8770。':'请打开聚合采样执行器完成配对与真实调用。'} <a href="http://127.0.0.1:8770/#/w/demo/apis?api_market=US" target="_blank" rel="noopener">Perplexity / 其他独立接口 ↗</a></div><div class="actions api-tabs"><button class="${baiMarket==='CN'?'primary':''}" onclick="baiChangeMarket('CN')">中国 · CN</button><button class="${baiMarket==='US'?'primary':''}" onclick="baiChangeMarket('US')">美国 · US</button><button onclick="baiRefresh()">刷新状态</button></div><section class="card"><div class="card-head"><h2>连接 B.AI</h2><span class="tag ${baiState.configured?'badge':'warn'}">${baiState.configured?'模型列表已读取':'待连接密钥'}</span></div><p class="subtitle">按 API 实际用量消耗 Credits；无需在这里购买订阅。不会自动充值。连接只读取账号的模型列表，不发起生成请求。</p><div class="actions"><button class="primary" ${baiToken?'':'disabled'} onclick="baiConnectModal()">${baiState.configured?'更换密钥 / 重新读取模型':'填写密钥并读取模型'}</button><a href="https://chat.b.ai/key" target="_blank" rel="noopener noreferrer">B.AI 密钥控制台 ↗</a><a href="https://docs.b.ai/llmservice/pricing-and-usage/" target="_blank" rel="noopener noreferrer">计费规则 ↗</a></div><p class="mono">${baiState.models.length} 个账号可见模型 · ${esc(baiState.fetched_at||'尚未读取')}</p></section><section class="card api-plan"><div class="card-head"><h2>本市场模型</h2><button ${baiState.configured?'':'disabled'} onclick="baiModelModal()">＋ 添加模型</button></div><p class="subtitle">只添加支持文本问答的固定模型；协议与联网能力以实际请求验证。Auto 不参与可重复评分。</p>${baiState.profiles.filter(p=>p.markets.includes(baiMarket)).map(p=>`<div class="source"><label><input type="checkbox" ${baiSelected.has(p.id)?'checked':''} onchange="this.checked?baiSelected.add('${p.id}'):baiSelected.delete('${p.id}')"> <b>${esc(p.name)}</b></label><span class="mono">${esc(p.model)} · ${esc(p.protocol)} · ${p.search?'请求联网':'文本接口'}</span></div>`).join('')||'<p class="muted">尚未添加此市场的模型。连接后，从账号返回的模型列表选择。</p>'}</section><section class="card api-plan"><h2>${baiMarket==='CN'?'中国':'美国'}市场采样任务</h2><div class="grid"><div>${input('品牌官网（仅记录测量对象）','bai-website',d.website||'')}${input('品牌名称 / 别名（| 分隔）','bai-brand',d.brand||'')}${area('SKU：每行“名称 | 精确别名 | 其他别名”','bai-skus',d.skus||'')}</div><div>${area('测试问题：每行一个，最多 10 个','bai-questions',d.questions??apiQuestions[baiMarket])}<p class="subtitle">最多 16 个模型、每批 64 次请求。提交后按所选模型实际用量计费；无自动重试、无自动切换模型。</p></div></div><button class="primary" id="bai-start" ${baiToken?'':'disabled'} onclick="baiStart()">运行所选模型</button><p id="bai-error" class="error" role="alert"></p></section><section class="card api-plan"><h2>采样结果与证据</h2><div class="actions">${baiRuns.filter(r=>r.market===baiMarket).map(r=>`<button onclick="baiOpen('${r.id}')">${esc(r.created_at.slice(0,16))} · ${esc(r.status)} · ${r.samples.length}/${r.planned}</button>`).join('')||'<p class="muted">此市场暂无运行记录。</p>'}</div>${baiResult()}</section>`}
function baiResult(){const r=baiActive;if(!r||r.market!==baiMarket)return '';return `<p class="mono">${esc(r.id)} · ${esc(r.status)}</p><p class="notice">提及分 = 100 × 完整、未提示目标的回答中精确别名命中数 / 有效回答数。错误与截断不计零；无有效样本不出分。这是本批模型 API 样本的提及率，不是推荐排名。</p>${table(['模型','完整 / 尝试 / 计划','品牌提及分','SKU 提及分'],r.summary.map(s=>`<tr><td>${esc(baiName(s.provider,r))}</td><td>${s.complete} / ${s.attempted} / ${r.prompts.length}</td><td>${s.brand_mention_score??'—'}<div class="row-meta">非提示有效样本 ${s.discovery_complete}</div></td><td>${s.skus.map(k=>`${esc(k.name)}：${k.score??'—'} (${k.mentions}/${k.denominator})`).join('<br>')||'未提供 SKU'}</td></tr>`).join(''))}<button onclick="baiExport('${r.id}')">↓ 导出原始证据包</button>${r.samples.map(s=>`<details class="api-answer"><summary>${esc(baiName(s.provider,r))} · 问题 ${s.question_index+1} · ${esc(s.status)}</summary><p>${esc(s.prompt)}</p><p class="mono">调用渠道：B.AI · ${esc(s.protocol)} · 请求模型 ${esc(s.model_requested)} · 返回模型 ${esc(s.model_returned||'未返回')} · 联网请求 ${s.search_requested?'开':'关'} / 执行证据 ${s.search_observed?'有':'未确认'}</p>${s.error?`<p class="error">${esc(s.error)}</p>`:`<pre class="evidence">${esc(s.answer)}</pre><pre class="evidence">${esc(JSON.stringify({citations:s.citations,retrieved_sources:s.retrieved_sources,usage:s.usage},null,2))}</pre><p class="mono">sha256:${esc(s.raw_sha256)}</p>`}</details>`).join('')}`}
function baiConnectModal(){baiCapture();modal(head('连接 B.AI API')+`<p>只填写 B.AI 密钥，不需要 OpenAI、Gemini 等厂商密钥。密钥仅存在独立本机进程内存，重启后需重新填写。</p>${input('B.AI API Key','bai-key','','password')}<p class="mono">https://api.b.ai/v1/models</p><button class="primary" id="bai-connect" onclick="baiConnect()">保存密钥并读取模型列表</button><p class="error" id="bai-connect-error" role="alert"></p>`);$('#bai-key').autocomplete='off'}
async function baiConnect(){try{$('#bai-connect').disabled=true;baiState=await baiFetch('connect',{key:$('#bai-key').value});$('#bai-key').value='';baiSelected.clear();closeOverlay();await baiRefresh();toast('模型列表已读取，请添加要测试的模型')}catch(e){if($('#bai-connect-error'))$('#bai-connect-error').textContent=e.message;if($('#bai-connect'))$('#bai-connect').disabled=false}}
function baiModelModal(){baiCapture();modal(head('添加固定模型')+`<label for="bai-model">账号可见模型</label><select id="bai-model" style="width:100%">${baiState.models.map(m=>`<option value="${esc(m.id)}">${esc(m.name)} · ${esc(m.id)}</option>`).join('')}</select>${input('显示名称（可留空，使用模型 ID）','bai-name','')}<label for="bai-protocol">调用协议</label><select id="bai-protocol" style="width:100%"><option value="chat">Chat Completions（文本接口）</option><option value="responses">Responses（支持的 GPT / DeepSeek 模型）</option><option value="anthropic">Messages（支持的 Claude 模型）</option></select><p class="subtitle">不会自动尝试其他协议或模型。模型在所选协议下是否可用，以实际返回为准。</p><label><input type="checkbox" id="bai-search"> 请求联网搜索（仅所选协议、模型支持时）</label><label><input type="checkbox" id="bai-cn" ${baiMarket==='CN'?'checked':''}> 加入中国市场</label><label><input type="checkbox" id="bai-us" ${baiMarket==='US'?'checked':''}> 加入美国市场</label><button class="primary" onclick="baiAddModel()">添加到采样列表</button><p id="bai-model-error" class="error" role="alert"></p>`)}
async function baiAddModel(){try{baiState=await baiFetch('profile',{model:$('#bai-model').value,name:$('#bai-name').value,protocol:$('#bai-protocol').value,search:$('#bai-search').checked,markets:[$('#bai-cn').checked?'CN':null,$('#bai-us').checked?'US':null].filter(Boolean)});closeOverlay();render()}catch(e){$('#bai-model-error').textContent=e.message}}
async function baiRefresh(){try{baiCapture();if(baiToken){const [s,r]=await Promise.all([baiFetch('state'),baiFetch('runs')]);baiState=s;baiRuns=r.runs;if(baiActive)baiActive=baiRuns.find(r=>r.id===baiActive.id)||baiActive}if(page==='bai')render()}catch(e){toast(e.message)}}
async function baiStart(){baiCapture();try{const d=baiDraft[baiMarket],skus=(d.skus||'').split('\n').filter(x=>x.trim()).map(x=>{const a=x.split('|').map(v=>v.trim()).filter(Boolean);return {name:a[0],aliases:a}});if(!baiSelected.size)throw Error('请先添加并勾选模型');$('#bai-start').disabled=true;const r=await baiFetch('run',{market:baiMarket,providers:[...baiSelected],website:d.website||'',brand_aliases:(d.brand||'').split('|').map(x=>x.trim()).filter(Boolean),skus,prompts:(d.questions||'').split('\n').map(x=>x.trim()).filter(Boolean)});await baiOpen(r.id)}catch(e){if($('#bai-error'))$('#bai-error').textContent=e.message;if($('#bai-start'))$('#bai-start').disabled=false}}
async function baiOpen(id){try{baiCapture();clearTimeout(baiTimer);baiActive=await baiFetch('run?id='+encodeURIComponent(id));await baiRefresh();if(['queued','running'].includes(baiActive.status))baiTimer=setTimeout(()=>{if(page==='bai')baiOpen(id)},4000)}catch(e){toast(e.message)}}
async function baiExport(id){try{downloadJSON(await baiFetch('export?id='+encodeURIComponent(id)),'signal-multimodel-'+id+'.json')}catch(e){toast(e.message)}}
const beforeBaiRender=render;render=function(){beforeBaiRender();if(page==='bai'){$('#view').innerHTML=baiPage();document.querySelector('.page-head .actions').innerHTML='';document.querySelector('main > .notice').innerHTML='<span>固定模型 · 同题比较 · 原始证据。主界面显示模型名称，调用渠道与版本在证据详情中保留。</span>';document.querySelector('.page-head .subtitle').textContent='连接一次，按市场选择多个模型进行采样。'}};
async function baiLoad(){if(!baiLocal())return;try{const r=await fetch('/api/bai/session');if(!r.ok)throw Error('聚合执行器配对失败');baiToken=(await r.json()).token;await baiRefresh()}catch(e){toast(e.message)}}
init();loadUpstreamCatalog();loadApiProviders();baiLoad();
